    const labels = { boundary: "\u6307\u5B9A\u9636\u6BB5\u8D77\u70B9", rename: "\u4FEE\u6539\u9636\u6BB5\u540D\u79F0", move: "\u8C03\u6574\u9636\u6BB5\u5206\u754C" };
