    $checks.prop("checked", !allChecked);
    $(this).html(allChecked ? '<i class="fa-solid fa-check-double"></i> \u5168\u9009' : '<i class="fa-solid fa-circle-xmark"></i> \u53D6\u6D88\u5168\u9009');
    updateBulkSelection();
