    lines.push("\u5BFC\u51FA\u5907\u4EFD\u4F1A\u81EA\u52A8\u628A\u6B63\u6587\u8BFB\u56DE\u6765\u6253\u5305\uFF0C\u4ECD\u7136\u81EA\u6210\u4E00\u4F53");
